import unicodedata
from PySide6.QtCore import QSortFilterProxyModel, Qt

def remove_vietnamese_accents(s):
    if not s:
        return ""
    s = str(s)
    # Convert 'đ' and 'Đ'
    s = s.replace('đ', 'd').replace('Đ', 'D')
    # Remove accents using NFKD
    s = unicodedata.normalize('NFKD', s).encode('ASCII', 'ignore').decode('utf-8')
    return s.lower()

